def _clean_html(value):
    if not value:
        return None
    text = html.unescape(value)
    text = re.sub(r"(?i)<\s*br\s*/?\s*>", "\n", text)
    text = re.sub(r"(?i)</\s*(p|div|li|ul|ol|h[1-6]|tr)\s*>", "\n", text)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r"\n\s+", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip() or None

def _search_url(start):
    return SITE.replace("start=0", "start=" + str(start))

def _detail_url(position_id):
    return "https://mercadolibre.eightfold.ai/api/pcsx/position_details?position_id=" + str(position_id) + "&domain=mercadolibre.com&hl=pt"

def _get_detail(ctx, position_id):
    cached = DETAIL_CACHE.get(str(position_id))
    if cached:
        return cached
    payload = json.loads(ctx.fetch(_detail_url(position_id)))
    return payload.get("data") or {}

def _job(position, detail):
    title = detail.get("name") or position.get("name")
    locations = detail.get("locations") or position.get("locations") or []
    location = detail.get("location") or (locations[0] if locations else None)
    url = detail.get("publicUrl") or detail.get("positionUrl") or position.get("positionUrl")
    if url and url.startswith("/"):
        url = "https://mercadolibre.eightfold.ai" + url

    out = {
        "url": url,
        "title": title,
        "company": COMPANY,
        "location": location,
        "description": _clean_html(detail.get("jobDescription")),
        "source": SITE,
    }

    if locations:
        out["locations"] = [str(x) for x in locations if x]

    external_id = detail.get("id") or position.get("id")
    if external_id is not None:
        out["external_id"] = str(external_id)

    department = detail.get("department") or position.get("department")
    if department:
        out["department"] = department

    workplace = detail.get("workLocationOption") or position.get("workLocationOption")
    if workplace:
        out["workplace_type"] = workplace

    return {k: v for k, v in out.items() if v not in (None, "", [])}

def crawl(ctx):
    seen = set()
    start = 0
    total = None

    while total is None or start < total:
        payload = json.loads(ctx.fetch(_search_url(start)))
        data = payload.get("data") or {}
        positions = data.get("positions") or []

        if total is None:
            total = int(data.get("count") or 0)

        if not positions:
            break

        for position in positions:
            position_id = position.get("id")
            if not position_id or position_id in seen:
                continue

            seen.add(position_id)
            detail = _get_detail(ctx, position_id)
            item = _job(position, detail)

            if item.get("url") and item.get("title") and item.get("location") and item.get("description"):
                yield item

        start += 10
